using UnscRelay.Core;
internal static class PrivacyDataChecks
{
 public static int Run(){var root=Directory.CreateTempSubdirectory("relay-privacy-");var count=0;void Check(bool good,string label){if(!good)throw new Exception(label);count++;Console.WriteLine("PASS privacy: "+label);}try{Directory.CreateDirectory(Path.Combine(root.FullName,"Editor"));Directory.CreateDirectory(Path.Combine(root.FullName,"AssistantScratch"));var editor=Path.Combine(root.FullName,"Editor","copy.txt");var archive=Path.Combine(root.FullName,"keys.vault");File.WriteAllText(editor,"draft");File.WriteAllText(archive,"encrypted fixture");File.WriteAllText(Path.Combine(root.FullName,"AssistantScratch","temporary.upload"),"temporary");var inventory=PrivacyData.Inventory(root.FullName);Check(inventory.Single(group=>group.Category=="editor").Bytes==5&&inventory.Single(group=>group.Category=="archive").Files==1,"inventory distinguishes archives editor copies and temporary files without returning names");var cancelled=PrivacyData.Cleanup(root.FullName,"editor",summary=>{Check(summary.Files==1&&summary.Bytes==5,"confirmation describes the verified open files");return false;});Check(!cancelled.Removed&&File.ReadAllText(editor)=="draft","refused cleanup removes no file");using(var busy=new FileStream(editor,FileMode.Open,FileAccess.Read,FileShare.Read)){try{PrivacyData.Cleanup(root.FullName,"editor",_=>true);throw new Exception("Busy copy deleted");}catch(IOException){Check(File.Exists(editor),"an externally open editor file blocks cleanup before deletion");}}var result=PrivacyData.Cleanup(root.FullName,"editor",_=>true);Check(result.Removed&&result.Files==1&&!File.Exists(editor)&&File.Exists(archive),"approved editor cleanup preserves the encrypted vault");foreach(var category in new[]{"archive","recordings","../outside"}){try{PrivacyData.Cleanup(root.FullName,category,_=>true);throw new Exception("Forbidden cleanup accepted");}catch(ArgumentException){Check(true,"cleanup accepts only the two fixed disposable categories");}}Check(File.Exists(Path.Combine(root.FullName,"AssistantScratch","temporary.upload")),"editor cleanup does not remove another category");var temporary=PrivacyData.Cleanup(root.FullName,"temporary",_=>true);Check(temporary.Removed&&temporary.Files==1&&File.Exists(archive),"temporary cleanup removes only the verified temporary category");Console.WriteLine("Privacy checks: "+count);return 0;}finally{root.Delete(true);}}
}
